import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

// Initialize the OBJ exporter
const exporter = new OBJExporter();

// Create the scene
const scene = createScene();

// Function to export a mesh or group to OBJ file
function exportMeshToOBJ(object, filePath) {
    // Create a temporary group to hold the object for export
    const tempGroup = new THREE.Group();

    // Clone the object to avoid modifying the original
    const clone = object.clone();

    // Reset position/rotation to export in local coordinates
    const originalPosition = clone.position.clone();
    const originalRotation = clone.rotation.clone();
    const originalQuaternion = clone.quaternion.clone();

    clone.position.set(0, 0, 0);
    clone.rotation.set(0, 0, 0);
    clone.quaternion.set(0, 0, 0, 1);

    tempGroup.add(clone);

    // Export to OBJ format
    const objData = exporter.parse(tempGroup);

    // Ensure directory exists
    const dir = path.dirname(filePath);
    fs.mkdirSync(dir, { recursive: true });

    // Write to file
    fs.writeFileSync(filePath, objData);

    console.log(`Exported: ${filePath}`);
}

// Function to merge all meshes in a group into a single mesh
function mergeMeshesInGroup(group) {
    const geometries = [];

    group.traverse((child) => {
        if (child instanceof THREE.Mesh && child.geometry) {
            // Clone and apply world matrix to get correct positioning
            const geomClone = child.geometry.clone();
            geomClone.applyMatrix4(child.matrixWorld);
            geometries.push(geomClone);
        }
    });

    if (geometries.length === 0) {
        return null;
    }

    // Merge all geometries
    const mergedGeometry = new THREE.BufferGeometry();
    const positions = [];
    const normals = [];

    for (const geom of geometries) {
        const posAttr = geom.getAttribute('position');
        const normAttr = geom.getAttribute('normal');

        if (posAttr) {
            for (let i = 0; i < posAttr.count; i++) {
                positions.push(posAttr.getX(i), posAttr.getY(i), posAttr.getZ(i));
            }
        }

        if (normAttr) {
            for (let i = 0; i < normAttr.count; i++) {
                normals.push(normAttr.getX(i), normAttr.getY(i), normAttr.getZ(i));
            }
        }
    }

    mergedGeometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    if (normals.length > 0) {
        mergedGeometry.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
    }

    return new THREE.Mesh(mergedGeometry);
}

// Process the scene
console.log('Starting mesh extraction...\n');

// Update world matrices for correct transformations
scene.updateMatrixWorld(true);

// Process each top-level part
scene.children.forEach((part) => {
    if (!(part instanceof THREE.Group)) return;

    const partName = part.name || 'unnamed_part';
    console.log(`\nProcessing part: ${partName}`);

