function exportMeshToOBJ(object, filePath) {
    // Create a temporary group to hold the object for export
    const tempGroup = new THREE.Group();

    // Clone the object to avoid modifying the original
    const clone = object.clone();

    // Reset position/rotation to export in local coordinates
